"""Explicit practical correction of twelve CTB explanations; no new material."""
import datetime,hashlib,json,re,sys
from pathlib import Path
root=Path(__file__).resolve().parents[2];p=Path(sys.argv[1]);read=lambda t:json.loads((p/'before'/(t+'.json')).read_text(encoding='utf-8'))
c=next(c for c in read('legal_courses') if c['slug']=='transito');topic=next(t for t in read('syllabus_topics') if t['id']==c['syllabus_topic_id']);us={u['unit_key']:u for u in read('legal_course_units') if u['course_id']==c['id']};es={e['unit_id']:e for e in read('legal_unit_explanations')}
source=next(s for s in json.loads((p/'source-index-verified.json').read_text(encoding='utf-8')) if s['slug']=='transito');assert hashlib.sha256((p/'sources/transito.html').read_bytes()).hexdigest()==source['sha256']
note='Atualização de 2016: a Lei 13.281 revogou a apreensão do veículo como penalidade do art. 256, IV, e o art. 262. A referência residual em artigos específicos do compilado não restaura essa penalidade. Remoção é medida administrativa distinta; apreensão de documentos ou placas não é apreensão do veículo.'
authored={
173:('Dois motoristas disputam corrida na via: examinam-se multa dez vezes, suspensão e medidas administrativas do artigo.','Um agente recolhe a habilitação e remove o veículo: essas medidas não são a penalidade revogada de apreensão.','A multa administrativa impede por si só responsabilidade criminal? Não; as esferas não se excluem automaticamente, e o enquadramento penal depende dos requisitos do tipo.'),
174:('Organizador promove demonstração de manobras na via sem permissão da autoridade; o artigo alcança promotor e condutor participante.','A defesa alega que só o motorista pode sofrer as penalidades: o §1º inclui os promotores.','O promotor do evento é sempre excluído das penalidades do artigo? Não; as penalidades alcançam promotores e condutores participantes.'),
175:('O motorista exibe derrapagem na via: a demonstração perigosa prevista é gravíssima, com multa dez vezes e suspensão.','Ele reincide em doze meses: a multa deste artigo é dobrada, sem confundir com qualquer infração reincidente.','Toda arrancada do veículo caracteriza automaticamente o artigo? Não; confronte a demonstração ou exibição de manobra perigosa e os elementos da conduta.'),
184:('O veículo circula na faixa exclusiva de transporte coletivo do inciso III: a infração é gravíssima, com multa e remoção.','A faixa é outra hipótese dos incisos I ou II: classificação e requisitos não podem ser transportados automaticamente do inciso III.','Todos os incisos do art. 184 são gravíssimos? Não; é preciso identificar a hipótese e a classificação do inciso correspondente.'),
210:('O condutor transpõe bloqueio viário policial sem autorização: incidem as sanções e medidas específicas do artigo.','O bloqueio não é policial: confira o art. 209, sem equiparar automaticamente as duas hipóteses.','Bloqueio policial e qualquer obstáculo viário têm sempre a mesma infração? Não; a natureza do bloqueio e os elementos do artigo distinguem as hipóteses.'),
229:('O alarme do veículo é utilizado indevidamente, perturbando o sossego em desacordo com as normas do Contran: o artigo prevê infração média.','O fato é uso de equipamento de som em volume ou frequência não autorizados: examine o art. 228, sem aplicar o 229 só pela palavra ruído.','O ruído autoriza aplicar automaticamente qualquer artigo sobre som? Não; é necessário identificar aparelho, conduta e a norma pertinente.'),
230:('O veículo possui dispositivo antirradar: confronte o inciso III e as consequências da infração gravíssima.','O defeito é em lâmpada ou iluminação: o inciso correspondente tem classificação própria; não se aplica automaticamente a classificação do antirradar.','Todas as condutas do art. 230 possuem a mesma gravidade? Não; seus grupos de incisos têm classificações e medidas próprias.'),
234:('A fiscalização identifica documento de habilitação adulterado: a infração é gravíssima; examine multa e remoção, além de eventual responsabilidade criminal própria.','O artigo ainda imprime apreensão do veículo na linha de penalidade: a revogação do art. 256, IV, impede tratá-la como penalidade atual.','A permanência da palavra apreensão no art. 234 restaura a penalidade revogada? Não; a redação residual deve ser lida com a revogação do rol geral e a distinção entre penalidade e medida administrativa.'),
238:('O condutor recusa entregar, mediante recibo, documento exigido para averiguar autenticidade: é a hipótese gravíssima descrita no artigo.','A exigência não é a verificação de autenticidade prevista aqui: não se enquadra toda recusa documental automaticamente no art. 238.','O artigo dispensa recibo para a entrega do documento? Não; exige entrega mediante recibo à autoridade ou ao agente para averiguação de autenticidade.'),
239:('O veículo está legalmente retido para regularização e o responsável o retira sem autorização: o artigo prevê infração gravíssima.','A autoridade permitiu a retirada: falta o elemento sem permissão da conduta descrita.','A simples retirada de qualquer veículo basta para este artigo? Não; exige veículo legalmente retido para regularização e retirada sem permissão.'),
253:('Um veículo bloqueia a via: a hipótese geral do art. 253 é gravíssima, com multa e remoção.','O veículo é usado deliberadamente, sem autorização, para interromper, restringir ou perturbar circulação: examine os elementos próprios do art. 253-A.','O art. 253 e o art. 253-A são sempre intercambiáveis? Não; o art. 253-A descreve hipótese própria, com elementos e consequências específicos.'),
256:('A autoridade aplica multa administrativa. Havendo também crime de trânsito, a penalidade administrativa não elimina automaticamente a responsabilidade penal.','A questão inclui apreensão do veículo no rol atual de penalidades: o inciso IV foi revogado em 2016; remoção pertence às medidas administrativas.','Remoção e apreensão do veículo são hoje duas penalidades do rol do art. 256? Não; a apreensão foi revogada como penalidade e a remoção é medida administrativa, com disciplina própria.'),
}
rows=[]
for n,(case,variation,question) in authored.items():
 u=us[f'art-{n}'];e=es[u['id']];data={f:e[f] for f in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 # Remove only the specifically inspected obsolete vehicle-penalty wording.
 if n!=256:data['simples']=re.sub(r',? e apreensão do veículo|, apreensão do veículo','',data['simples'])
 data['atencao']=[t for t in data['atencao'] if 'apreens' not in t.lower()]+[note]
 data['exemplo']=case+' Variação: '+variation;data['prova']=[question]
 data['pontos']=[t for t in data['pontos'] if 'apreens' not in t.lower()]+['Diferencie penalidade de multa ou suspensão da medida administrativa de remoção.']
 rows.append({'course_slug':c['slug'],'course_id':c['id'],'syllabus_topic_id':topic['id'],'edition_id':topic['edition_id'],'unit_key':u['unit_key'],'unit_id':u['id'],'content_sha256':u['content_sha256'],**data,'expected':e})
law={'slug':c['slug'],'title':c['title'],'units':len(rows),'scope_type':'targeted_correction','course_current_units':sum(u['content_status']=='current' for u in us.values()),'target_unit_keys':[r['unit_key'] for r in rows],'source_url':c['source_url'],'source_sha256':source['sha256'],'source_checked_at':source['checked_at']}
cp=next(c for c in read('legal_courses') if c['slug']=='codigo-penal');cp_topic=next(t for t in read('syllabus_topics') if t['id']==cp['syllabus_topic_id']);cp_unit=next(u for u in read('legal_course_units') if u['course_id']==cp['id'] and u['unit_key']=='art-216-b');cp_fix=json.loads((root/'docs/library/cp216b-body-correction-2026-10-11.json').read_text(encoding='utf-8'))
cp_ev=next(s for s in json.loads((p/'source-index-verified.json').read_text(encoding='utf-8')) if s['slug']=='codigo-penal')
rows.append({'course_slug':cp['slug'],'course_id':cp['id'],'syllabus_topic_id':cp_topic['id'],'edition_id':cp_topic['edition_id'],'unit_key':cp_unit['unit_key'],'unit_id':cp_unit['id'],'content_sha256':cp_fix['changes'][0]['content_sha256'],'simples':'O art. 216-B pune produzir, fotografar, filmar ou registrar conteúdo de nudez ou ato sexual ou libidinoso íntimo e privado, sem autorização dos participantes. A pena é detenção de seis meses a um ano e multa. O parágrafo único alcança montagem destinada a incluir pessoa em cena de nudez ou ato sexual ou libidinoso íntimo.','pontos':['A conduta do caput envolve registrar conteúdo íntimo e privado sem autorização dos participantes.','Montagem para incluir pessoa na cena é hipótese expressa do parágrafo único.','Pena: detenção de seis meses a um ano e multa.'],'atencao':['Não confunda registro não autorizado com divulgação de conteúdo íntimo: a divulgação tem disciplina própria no art. 218-C.','O título histórico Sedução pertencia ao dispositivo seguinte revogado; não é parte da regra do art. 216-B.'],'exemplo':'Uma pessoa grava, sem autorização dos participantes, ato íntimo e privado: confronta-se o caput do art. 216-B. Variação: A cena foi produzida por montagem para incluir outra pessoa: o parágrafo único descreve essa hipótese, sem exigir que a gravação da cena tenha ocorrido como no caput.','prova':['Uma montagem está automaticamente fora do art. 216-B porque não registra uma cena realmente ocorrida? Não; o parágrafo único prevê montagem destinada a incluir pessoa em cena íntima de nudez ou ato sexual ou libidinoso.'],'termos':[],'remissoes':['Art. 218-C'],'expected':es[cp_unit['id']]})
cp_law={'slug':cp['slug'],'title':cp['title'],'units':1,'scope_type':'targeted_correction','course_current_units':401,'target_unit_keys':['art-216-b'],'source_url':cp['source_url'],'source_sha256':cp_ev['sha256'],'source_checked_at':cp_ev['checked_at']}
(root/'docs/library/article-explanations-ctb-penalties-2026-10-11.json').write_text(json.dumps({'version':'2026-10-11-ctb-penalties','checked_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'laws':[law,cp_law],'units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'existing CTB/CP explanations corrected')
